const variables=[
	{label:'Microstructure',sub:'grains · phases · particles',kicker:'layer 01 · microstructure',title:'The sheet is not continuous matter',text:'Grains, second phases, inclusions, and precipitates determine where slip begins and how plastic strain is distributed. Grain boundaries can strengthen the sheet, while coarse particles or inclusions can become damage nucleation sites.',measure:'Optical metallography, SEM, EBSD; report grain size and phase fraction.',effect:'Fine grains often raise yield strength; particles can raise strength but reduce damage tolerance when they debond.',model:'Yield stress, damage initiation, and spatial variability of properties.',reference:'Hall (1951); Petch (1953); ASTM E112 for grain size.',image:'https://commons.wikimedia.org/wiki/Special:FilePath/Copper%20alloy%20microstructure.jpg?width=1000',caption:'Copper alloy microstructure · optical metallography',source:'https://commons.wikimedia.org/wiki/File:Copper_alloy_microstructure.jpg'},
	{label:'Texture',sub:'crystal orientation',kicker:'layer 02 · crystallographic texture',title:'Processing leaves a directional fingerprint',text:'Rolling rotates crystals toward preferred orientations. The result is a texture: the aggregate does not offer the same slip resistance in every direction. Texture is the microstructural origin of directional yield and plastic strain ratios.',measure:'EBSD orientation maps, pole figures, inverse pole figures, ODF.',effect:'The same nominal strain can produce different width and thickness changes at 0°, 45°, and 90° to rolling direction.',model:'Anisotropic yield function or crystal-plasticity orientation set.',reference:'Bunge (1982), Texture Analysis in Materials Science; Kocks, Tomé & Wenk (1998).',image:'https://upload.wikimedia.org/wikipedia/commons/6/6c/EBSD_orientation_map_of_ferrous_lath_martensite.jpg',caption:'EBSD orientation map of ferrous lath martensite',source:'https://commons.wikimedia.org/wiki/File:EBSD_orientation_map_of_ferrous_lath_martensite.jpg'},
	{label:'Mechanical response',sub:'yield · hardening · ductility',kicker:'layer 03 · mechanical response',title:'A tensile curve is a path, not the material',text:'Yield stress tells us when plastic flow starts; the slope after yielding tells us how resistance evolves; uniform elongation indicates when diffuse instability begins on that particular loading path.',measure:'Uniaxial tensile test: true stress, true strain, yield point, UTS, uniform elongation.',effect:'A high yield stress can improve strength while reducing available plastic margin; a high hardening rate can delay localization.',model:'Flow curve σ = f(εᵖ), yield stress, and hardening parameters.',reference:'Swift (1952); ISO 6892-1 / ASTM E8/E8M.',image:'https://upload.wikimedia.org/wikipedia/commons/4/43/Modern_universal_testing_machine.jpg',caption:'Modern universal testing machine used to obtain tensile response',source:'https://commons.wikimedia.org/wiki/File:Modern_universal_testing_machine.jpg'},
	{label:'Anisotropy',sub:'direction changes the answer',kicker:'layer 04 · planar anisotropy',title:'Direction becomes a measurable variable',text:'For sheet, compare properties along the rolling direction (0°), diagonal direction (45°), and transverse direction (90°). The plastic strain ratio r = εᵂᵖ / εᵗᵖ records how width strain compares with thickness strain during tensile plastic flow.',measure:'Three directional tensile tests; calculate r-values and directional yield stresses.',effect:'Anisotropy causes earing in cups, directional thinning, and different forming limits around a part.',model:'Hill ’48 or Barlat coefficients calibrated to directional data.',reference:'Hill (1948); Lankford, Snyder & Bausher (1950).',image:'https://upload.wikimedia.org/wikipedia/commons/c/ca/BrutTrempe316L.jpg',caption:'Real 316L material image associated with EBSD texture mapping',source:'https://commons.wikimedia.org/wiki/File:BrutTrempe316L.jpg'},
	{label:'Strain hardening',sub:'the material remembers plastic work',kicker:'layer 05 · strain hardening',title:'Hardening competes with localization',text:'As dislocations accumulate, additional plastic strain requires higher stress. This hardening can stabilize a tensile specimen, but the balance depends on the current strain path and stress state. The exponent n is a compact measure, not a universal constant.',measure:'Fit true stress–true plastic strain after elastic correction; report fitting interval and law.',effect:'Higher n generally delays diffuse necking in uniaxial tension, but does not guarantee a higher forming limit under biaxial loading.',model:'Hollomon, Swift, Ludwik, Voce, or a tabulated flow curve.',reference:'Hollomon (1945); Voce (1948); Swift (1952).',image:'https://upload.wikimedia.org/wikipedia/commons/0/0a/TEM_micrograph_dislocations_precipitate_stainless_steel_2.jpg',caption:'TEM micrograph showing dislocations and precipitates in stainless steel',source:'https://commons.wikimedia.org/wiki/File:TEM_micrograph_dislocations_precipitate_stainless_steel_2.jpg'},
	{label:'Stress state + path',sub:'how the process loads the sheet',kicker:'layer 06 · stress state and strain path',title:'The route to the same strain matters',text:'Uniaxial tension, plane strain, and biaxial stretching activate different stability and damage mechanisms. Two points with the same major strain can have different histories and different proximity to localization.',measure:'DIC strain fields, thickness measurement, force history, and stress reconstruction.',effect:'Changing friction, tool radius, blank-holder force, or draw bead changes the local path and therefore the safe process window.',model:'Yield surface + hardening law + forming limit or damage criterion.',reference:'Marciniak & Kuczyński (1967); Keeler & Backofen (1963).',image:'https://upload.wikimedia.org/wikipedia/commons/4/41/Sheet_metal_shop_fabricates_a_metal_bracket_for_medical_use_%289494170%29.jpg',caption:'Real sheet-metal fabrication operation',source:'https://commons.wikimedia.org/wiki/File:Sheet_metal_shop_fabricates_a_metal_bracket_for_medical_use_(9494170).jpg'}
];
const variableDetails=[
	[{k:'metallography → grain statistics',h:'Turn a beautiful image into a distribution',p:'Segment the etched image, calibrate the scale bar, and report mean grain size, standard deviation, aspect ratio, and outlier population. The question is not “what does it look like?” but “how heterogeneous is the slip length from grain to grain?”',e:'Hall–Petch: σᵧ = σ₀ + kᵧ d⁻¹ᐟ²',n:'Next: compare grain size with local strain maps after forming.'},{k:'second phases and inclusions',h:'Strengthening can create a damage route',p:'Use SEM/EDS to identify particles, then inspect void nucleation around them after deformation. Particle size, spacing, interface strength, and morphology connect alloy processing to fracture strain.',e:'damage initiates where plastic incompatibility concentrates',n:'Next: follow the same region into EBSD and texture.'},{k:'case study · dual-phase steel',h:'Ferrite–martensite contrast',p:'In dual-phase steels, soft ferrite accommodates strain while hard martensite islands raise strength. An interface can delay uniform flow or become a site for damage, depending on morphology and loading path.',e:'microstructure → local strain partitioning → forming limit',n:'Advance to 02 Texture.'}],
	[{k:'EBSD acquisition',h:'What the detector actually measures',p:'A tilted polished surface produces Kikuchi patterns. Indexing maps each scan point to a crystal orientation and confidence metric. Step size must resolve the smallest feature relevant to deformation.',e:'orientation + image quality + confidence index',n:'Next: turn orientations into a texture description.'},{k:'pole figures and ODF',h:'From millions of pixels to a directional population',p:'Pole figures show the probability of selected crystal directions relative to the sheet axes. The orientation distribution function is the quantitative representation used to calculate effective anisotropy or feed a crystal-plasticity model.',e:'ODF f(g) → texture components → directional response',n:'Next: connect texture to yield stress and r-value.'},{k:'case study · rolled sheet',h:'Why rolling history survives in the forming response',p:'A rolled sheet can show bands of preferred orientations. Those orientations alter which slip systems activate at 0°, 45°, and 90° to rolling direction, producing directional yield and earing in a drawn cup.',e:'texture → slip activity → planar anisotropy',n:'Advance to 03 Mechanical response.'}],
	[{k:'extensometer / gauge length',h:'The classical average',p:'An extensometer measures displacement over a gauge length and provides a robust average strain. It cannot resolve the spatial onset of a neck, and its gauge length filters local heterogeneity.',e:'ε = ΔL / L₀',n:'Next: replace one average with a field.'},{k:'DIC: full-field kinematics',h:'Every subset becomes a local measurement',p:'Digital image correlation tracks a stochastic surface pattern between frames. It returns displacement and strain fields, so localization, shear bands, and strain-path changes can be measured before the force curve shows a clear failure.',e:'u(x,y,t) → ∇u → ε₁, ε₂, shear strain',n:'Next: measure thickness and volume, not only the visible face.'},{k:'3D DIC, CT, and in-situ methods',h:'The missing dimension matters',p:'Stereo-DIC estimates out-of-plane motion; X-ray CT reveals internal voids; in-situ SEM or synchrotron diffraction links evolving microstructure to load. These methods reduce the assumption that the specimen is uniform through thickness.',e:'surface field + thickness / void data → local constitutive evidence',n:'Advance to 04 Anisotropy.'}],
	[{k:'r-value',h:'A compact signature of planar anisotropy',p:'During a tensile test, measure width and thickness plastic strains. The Lankford coefficient r = εᵂᵖ/εᵗᵖ compares how the sheet contracts in width versus thickness. Repeat at 0°, 45°, and 90° to rolling direction.',e:'r = εᵂᵖ / εᵗᵖ',n:'Next: test whether one coefficient can represent the full surface.'},{k:'yield locus',h:'Measure directions in stress space',p:'Use uniaxial, shear, and biaxial tests to map initial yield points. The anisotropic yield function is judged by whether one surface reproduces all directions, not only three tensile strengths.',e:'f(σ₁,σ₂,σ₃; F,G,H,L,M,N) = 0',n:'Next: see the macroscopic trace in a cup.'},{k:'case study · earing',h:'Anisotropy becomes a visible part defect',p:'A deep-drawn cup develops ears at preferred angles when plastic flow is direction-dependent. Earing height is therefore a process-level validation of texture and anisotropic coefficients.',e:'Δh(θ) → calibrate anisotropic plasticity',n:'Advance to 05 Strain hardening.'}],
	[{k:'true stress–true strain',h:'Build the flow curve correctly',p:'Convert force and gauge length into true quantities only while the deformation is homogeneous; after necking, use local DIC or inverse identification. Subtract elastic strain to obtain plastic strain before fitting a law.',e:'σᵗ = F/Aᵢ · (1+εᵉ); εᵖ = εᵗ − σᵗ/E',n:'Next: ask what dislocation structures produce the slope.'},{k:'dislocation storage',h:'Hardening is a changing resistance',p:'Dislocations interact, accumulate, rearrange, and sometimes annihilate. The macroscopic slope dσ/dεᵖ is an aggregate response to these mechanisms, not a microstructural constant independent of path.',e:'dσ/dεᵖ competes with geometric softening',n:'Next: test the model under a different path.'},{k:'case study · forming limit',h:'High n helps, but does not solve every path',p:'A material with a larger uniaxial hardening exponent can delay diffuse necking, yet plane-strain or biaxial forming may still localize early. The fitting range and stress path must accompany every reported n-value.',e:'n is path-dependent evidence, not a universal ranking',n:'Advance to 06 Stress state + path.'}],
	[{k:'stress triaxiality',h:'The same strain can carry a different risk',p:'The ratio of mean stress to von Mises stress controls the tendency for void growth. Shear-dominated paths can activate different damage mechanisms from tensile triaxial paths even at comparable equivalent strain.',e:'η = σₘ / σ̄',n:'Next: plot the path in principal-strain space.'},{k:'strain-path history',h:'A point is not enough; record the route',p:'DIC histories reveal whether a point moved from uniaxial tension toward plane strain, or from biaxial stretching toward shear. Forming-limit data must therefore preserve loading history and necking criterion.',e:'β = dε₂ / dε₁; path curvature matters',n:'Next: use the history in a constitutive update.'},{k:'process case · draw bead',h:'Tooling changes the local experiment',p:'A draw bead raises restraint and changes tension, bending, and unbending locally. Friction and blank-holder force alter the strain path that the material experiences, so a coupon property alone cannot predict the component.',e:'tool geometry + contact → local stress path → failure risk',n:'Topic 02 complete: the variables are connected.'}]
];
const exploreFeeds=[
	[{type:'method',title:'ASTM E112 grain-size measurement',text:'Compare line-intercept and planimetric methods; decide what “grain size” means before correlating it with yield stress.',url:'https://store.astm.org/e0112-24.html',label:'open standard ↗'},{type:'paper',title:'Hall–Petch strengthening',text:'The classic relation connects grain size to yield stress. Read it as a statistical trend, not a substitute for texture or phase analysis.',url:'https://www.osti.gov/search/term/Hall-Petch',label:'read repository ↗'},{type:'case',title:'Dual-phase steel: local strain partitioning',text:'Follow ferrite–martensite contrast from image segmentation to local deformation and damage initiation.',url:'https://www.osti.gov/search/term/dual-phase%20steel%20strain%20partitioning',label:'open repository ↗'}],
	[{type:'method',title:'EBSD acquisition and indexing',text:'Use Kikuchi patterns, indexing confidence, scan step and sample preparation to understand what an orientation map actually measures.',url:'https://www.ebsd.com/ebsd-explained/what-is-ebsd',label:'open EBSD explanation ↗'},{type:'data',title:'Pole figures and ODF with MTEX',text:'Move from orientation data to pole figures, orientation distribution functions and quantitative texture components with an open research toolbox.',url:'https://mtex-toolbox.github.io/',label:'open MTEX toolbox ↗'},{type:'case',title:'Texture and cup earing',text:'Study how rolling texture in AA6016 produces 0°/180° ears and how crystal-plasticity FEM reproduces the measured cup profile.',url:'https://www.jstage.jst.go.jp/article/matertrans/53/11/53_L-M2012825/_article',label:'open J-STAGE study ↗'}],
	[{type:'method',title:'Digital image correlation (DIC)',text:'Understand subset tracking, calibration, spatial resolution and strain filtering before trusting a full-field map.',url:'https://www.correlatedsolutions.com/technology',label:'read DIC method ↗'},{type:'data',title:'Mechanical testing with DIC',text:'Use synchronized force, displacement and full-field strain to identify localization and improve the mechanical response used in forming analysis.',url:'https://static1.squarespace.com/static/5fb2d3df2ff02b3fcda6f398/t/61eebd0e0310c471ea85b076/1643035920412/A_Good_Practices_Guide_for_Digital_Image+(1).pdf',label:'open measurement guide ↗'},{type:'advanced',title:'3D-DIC, CT and in-situ diffraction',text:'Combine surface kinematics with out-of-plane motion, internal voids or lattice strain to reduce hidden assumptions.',url:'https://www.correlatedsolutions.com/vic-3d',label:'open 3D method ↗'}],
	[{type:'method',title:'Lankford r-value protocol',text:'Measure width and thickness plastic strains at 0°, 45° and 90°. The result is a directional datum, not a generic ductility number.',url:'https://www.iso.org/standard/67452.html',label:'read standard ↗'},{type:'model',title:'Hill 1948 anisotropic yield',text:'See how directional yield stresses and r-values become coefficients in an anisotropic yield function.',url:'https://docs.software.vt.edu/abaqusv2024/English/SIMACAEMATRefMap/simamat-c-anisoyield.htm',label:'open model docs ↗'},{type:'case',title:'Earing as validation',text:'Use cup height versus angle to validate texture, anisotropic coefficients and the direction convention in the FE model.',url:'https://publica.fraunhofer.de/handle/publica/213256',label:'open repository ↗'}],
	[{type:'method',title:'True stress and plastic strain',text:'Convert force and displacement only while deformation is homogeneous; after necking, use local fields or inverse identification.',url:'https://www.nde-ed.org/EducationResources/CommunityCollege/Materials/Structure/strengthening.htm',label:'read methodology ↗'},{type:'model',title:'Hollomon, Swift and Voce',text:'Compare fitting ranges, yield transition and saturation. A good fit must reproduce the strain interval used by the forming process.',url:'https://docs.software.vt.edu/abaqusv2024/English/SIMACAEMATRefMap/simamat-c-hardening.htm',label:'compare model docs ↗'},{type:'case',title:'Hardening versus forming limit',text:'Test the tempting but incomplete claim that larger n always means better formability under every stress path.',url:'https://www.abaqus.com/products/solvers/simulation/metal-forming.html',label:'open forming route ↗'}],
	[{type:'concept',title:'Stress triaxiality',text:'Mean stress divided by equivalent stress helps distinguish void growth from shear-dominated failure.',url:'https://www.osti.gov/search/term/stress%20triaxiality%20ductile%20fracture',label:'read repository ↗'},{type:'data',title:'Strain-path measurement with DIC',text:'Track β = dε₂/dε₁ through time rather than reporting only the final point on an FLD.',url:'https://www.correlatedsolutions.com/technology',label:'open DIC method ↗'},{type:'case',title:'Draw bead and local loading path',text:'Tool contact changes restraint, bending and unbending; the component is a new experiment with its own local history.',url:'https://www.abaqus.com/products/solvers/simulation/metal-forming.html',label:'open forming route ↗'}]
];
