let variableIndex=0,detailIndex=0;
function getYouTubeId(url){try{const parsed=new URL(url);if(parsed.hostname==='youtu.be')return parsed.pathname.slice(1);if(parsed.hostname.endsWith('youtube.com'))return parsed.searchParams.get('v')||parsed.pathname.split('/').filter(Boolean).pop()}catch{}return null}
function getYouTubeSearchUrl(title){return `https://www.youtube.com/results?search_query=${encodeURIComponent(title)}`}
function openExternal(url){window.open(url,'_blank','noopener,noreferrer')}
async function copyVideoLink(url){try{await navigator.clipboard.writeText(url);$('#copyVideoLink').textContent='Link copiado ✓'}catch{$('#copyVideoLink').textContent='Selecione e copie o link abaixo';$('#videoLinkText').select()}}
function openResource(item){const videoId=getYouTubeId(item.url),isVideo=Boolean(videoId),researchUrl=item.researchUrl||item.next||item.url,hasResearch=Boolean(item.researchUrl);$('#resourceModalImage').src=item.image;$('#resourceModalImage').alt=item.title;$('#resourceModalType').textContent=`${item.type} · linked investigation`;$('#resourceModalTitle').textContent=item.title;$('#resourceModalText').textContent=item.text;$('#resourceModalNote').textContent=isVideo?'Escolha como continuar fora da apresentação: o YouTube abre em uma aba externa e a segunda opção leva a uma fonte técnica sobre este ensaio.':hasResearch?'Escolha uma fonte principal ou uma segunda referência técnica do PDF para aprofundar o ensaio.':item.access||'A fonte abre em nova aba. O resumo e a imagem permanecem disponíveis nesta ferramenta para orientar a leitura.';$('#resourceModalLink').href=item.url;$('#resourceModalLink').textContent=isVideo?'Abrir vídeo no YouTube ↗':'Abrir fonte principal ↗';$('#resourceModalLink').onclick=event=>{if(isVideo){event.preventDefault();openExternal(item.url)}};$('#resourceModalFallback').href=researchUrl;$('#resourceModalFallback').textContent=isVideo?'Ler pesquisa / referência técnica ↗':'Abrir segunda referência técnica ↗';$('#resourceModalFallback').hidden=!hasResearch&&!isVideo;$('#resourceAdditionalLinks').innerHTML=(item.additionalReferences||[]).map(reference=>`<a class="resource-fallback-link" href="${reference.url}" target="_blank" rel="noopener noreferrer">${reference.label} ↗</a>`).join('');$('#resourceAdditionalLinks').hidden=!(item.additionalReferences||[]).length;$('#videoLinkOption').hidden=!isVideo;$('#videoLinkText').value=isVideo?item.url:'';$('#copyVideoLink').textContent='Copiar link do YouTube';$('#copyVideoLink').onclick=()=>copyVideoLink(item.url);$('#resourceModal').classList.add('open');$('#resourceModal').setAttribute('aria-hidden','false')}
function closeResource(){document.activeElement?.blur();$('#resourceModal').classList.remove('open');$('#resourceModal').setAttribute('aria-hidden','true')}
function renderDetail(){const data=variableDetails[variableIndex][detailIndex];$$('.variable-column-button').forEach((button,i)=>button.classList.toggle('active',i===detailIndex));$('#variableDetail').innerHTML=`<div class="detail-kicker">${data.k}</div><h4>${data.h}</h4><p>${data.p}</p><div class="detail-equation">${data.e}</div><button class="detail-next" id="nextRouteButton">What's next? <span>${data.n.replace('Next: ','')}</span></button>`;$('#nextRouteButton').onclick=()=>openResource(nextResources[variableIndex]);$('#exploreFeed').innerHTML=exploreFeeds[variableIndex].map((item,i)=>`<article class="explore-card" data-feed="${i}"><img src="${item.image}" alt="${item.title}"><div><div class="feed-type">${item.type} · linked investigation</div><h4>${item.title}</h4><p>${item.text}</p><a href="${item.url}" target="_blank" rel="noreferrer">${item.label}</a></div></article>`).join('');$$('.explore-card').forEach((card,i)=>card.onclick=event=>{if(event.target.tagName!=='A')openResource(exploreFeeds[variableIndex][i])})}
function renderVariable(){const data=variables[variableIndex];detailIndex=0;$('#variableRail').innerHTML=variables.map((v,i)=>`<button class="variable-button ${i===variableIndex?'active':''}" data-variable="${i}"><b>${String(i+1).padStart(2,'0')} · ${v.label}</b><span>${v.sub}</span></button>`).join('');$$('.variable-button').forEach(button=>button.onclick=()=>{variableIndex=+button.dataset.variable;renderVariable()});$$('.variable-column-button').forEach(button=>button.onclick=()=>{detailIndex=+button.dataset.detail;renderDetail();openResource(exploreFeeds[variableIndex][detailIndex])});$('#variableImage').src=data.image;$('#variableImage').alt=data.caption;$('#variableCaption').textContent=data.caption;$('#variableSource').href=data.source;$('#variableKicker').textContent=data.kicker;$('#variableTitle').textContent=data.title;$('#variableText').textContent=data.text;$('#variableMeasure').textContent=data.measure;$('#variableEffect').textContent=data.effect;$('#variableModel').textContent=data.model;$('#variableReference').textContent=data.reference;renderDetail()}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
