function chartFrame(ctx,w,h,xlab,ylab){ctx.fillStyle='#101817';ctx.fillRect(0,0,w,h);const p={l:70,r:30,t:32,b:58};ctx.strokeStyle='#263b37';ctx.lineWidth=1;for(let i=1;i<6;i++){const x=p.l+i*(w-p.l-p.r)/6,y=p.t+i*(h-p.t-p.b)/6;line(ctx,x,p.t,x,h-p.b,'#1e302d');line(ctx,p.l,y,w-p.r,y,'#1e302d')}line(ctx,p.l,p.t,p.l,h-p.b,'#81918a',2);line(ctx,p.l,h-p.b,w-p.r,h-p.b,'#81918a',2);ctx.fillStyle=paper;ctx.font='600 11px DM Mono';ctx.fillText(xlab,w/2-55,h-18);ctx.save();ctx.translate(18,h/2+30);ctx.rotate(-Math.PI/2);ctx.fillText(ylab,0,0);ctx.restore();return p}
function drawFLC(){const c=$('#flcCanvas'),{ctx,w,h}=resizeCanvas(c),p=chartFrame(ctx,w,h,'minor strain ε₂','major strain ε₁');const X=x=>p.l+(x+.55)/(1.55)*(w-p.l-p.r),Y=y=>h-p.b-(y/.9)*(h-p.t-p.b);ctx.strokeStyle=cyan;ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=100;i++){const x=-.5+i/100*1.5,y=.43+.11*Math.exp(-Math.pow((x-.1)/.3,2))-.08*x; i?ctx.lineTo(X(x),Y(y)):ctx.moveTo(X(x),Y(y))}ctx.stroke();const beta=+$('%');}
function drawFLCCorrect(){const c=$('#flcCanvas'),{ctx,w,h}=resizeCanvas(c),p=chartFrame(ctx,w,h,'minor strain ε₂  (compression ← | → biaxial)','major strain ε₁'),X=x=>p.l+(x+.55)/(1.55)*(w-p.l-p.r),Y=y=>h-p.b-(y/.9)*(h-p.t-p.b),curve=x=>.43+.11*Math.exp(-Math.pow((x-.1)/.3,2))-.08*x;ctx.fillStyle='#17332f';ctx.beginPath();ctx.moveTo(X(-.5),Y(0));for(let i=0;i<=100;i++){const x=-.5+i/100*1.5;ctx.lineTo(X(x),Y(curve(x)))}ctx.lineTo(X(1),Y(0));ctx.closePath();ctx.fill();ctx.strokeStyle=cyan;ctx.lineWidth=4;ctx.beginPath();for(let i=0;i<=100;i++){const x=-.5+i/100*1.5;i?ctx.lineTo(X(x),Y(curve(x))):ctx.moveTo(X(x),Y(curve(x)))}ctx.stroke();ctx.fillStyle='#79918a';ctx.font='10px DM Mono';ctx.fillText('SAFE / measured forming window',X(-.42),Y(.12));ctx.fillStyle=orange;ctx.fillText('localized necking / failure',X(.32),Y(.78));const beta=+$('#minorRatio').value,n=+$('#nExponent').value,thickness=+$('#thickness').value,limit=(.35+.55*n-.12*Math.abs(beta-.15))*(.92+.08*thickness/1.2),endY=Math.max(-.45,Math.min(.9,beta*limit/.48)),pathInSafe=endY<=curve(beta);ctx.strokeStyle=lime;ctx.lineWidth=3;ctx.setLineDash([8,5]);line(ctx,X(0),Y(0),X(beta),Y(endY),lime,3);ctx.setLineDash([]);ctx.fillStyle=pathInSafe?lime:orange;ctx.beginPath();ctx.arc(X(beta),Y(endY),9,0,Math.PI*2);ctx.fill();ctx.fillStyle=paper;ctx.font='600 11px DM Mono';ctx.fillText(`path β=${beta.toFixed(2)} · ${pathInSafe?'SAFE':'FAILURE RISK'}`,Math.min(X(beta)+12,w-205),Y(endY)-10);ctx.fillText(`limit ε₁=${limit.toFixed(2)}`,Math.min(X(beta)+12,w-205),Y(endY)+9);$('#limitReadout').textContent=`ε₁ = ${limit.toFixed(2)} · ${pathInSafe?'safe path':'above FLC'}`}
function drawYield(){const c=$('#yieldCanvas'),{ctx,w,h}=resizeCanvas(c);ctx.fillStyle='#151c1c';ctx.fillRect(0,0,w,h);const cx=w*.49,cy=h*.51,r=Math.min(w,h)*.34;ctx.strokeStyle='#30413c';ctx.lineWidth=1;for(let i=0;i<8;i++){const a=i*Math.PI/4;line(ctx,cx,cy,cx+Math.cos(a)*r*1.25,cy+Math.sin(a)*r*1.25,'#26332f')}ctx.strokeStyle='#47d4d255';ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.stroke();ctx.strokeStyle=orange;ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=6;i++){const a=i*Math.PI/3;const rr=$('#yieldCriterion').value==='tresca'?r*(.92+.08*(i%2)):$('#yieldCriterion').value==='hill'?r*(.92+.08*Math.abs(Math.cos(a))):r;i?ctx.lineTo(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr):ctx.moveTo(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr)}ctx.closePath();ctx.stroke();const s1=+$('{bad}');}
function drawYieldCorrect(){const c=$('#yieldCanvas'),{ctx,w,h}=resizeCanvas(c),criterion=$('#yieldCriterion').value,s1=+$('#sigma1').value,s2=+$('#sigma2').value,cx=w*.48,cy=h*.53,r=Math.min(w,h)*.31;ctx.fillStyle='#101817';ctx.fillRect(0,0,w,h);ctx.fillStyle='#17332f';ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fill();for(let i=0;i<12;i++){const a=i*Math.PI/6;line(ctx,cx,cy,cx+Math.cos(a)*r*1.4,cy+Math.sin(a)*r*1.4,'#29413c')}ctx.strokeStyle=orange;ctx.lineWidth=4;ctx.beginPath();for(let i=0;i<=180;i++){const a=i/180*Math.PI*2,shape=criterion==='tresca'?1+.1*Math.cos(6*a):criterion==='hill'?1+.13*Math.cos(2*a):1;i?ctx.lineTo(cx+Math.cos(a)*r*shape,cy+Math.sin(a)*r*shape):ctx.moveTo(cx+Math.cos(a)*r*shape,cy+Math.sin(a)*r*shape)}ctx.stroke();const px=cx+(s1-s2*.5)*r*.58,py=cy-s2*r*.58,eq=criterion==='tresca'?Math.max(Math.abs(s1-s2),Math.abs(s2),Math.abs(s1)):Math.sqrt(s1*s1-s1*s2+s2*s2);ctx.strokeStyle=lime;ctx.setLineDash([6,5]);line(ctx,cx,cy,px,py,lime,2);ctx.setLineDash([]);ctx.fillStyle=cyan;ctx.beginPath();ctx.arc(px,py,10,0,Math.PI*2);ctx.fill();ctx.fillStyle=paper;ctx.font='600 11px DM Mono';ctx.fillText(`current: σ₁=${s1.toFixed(2)}, σ₂=${s2.toFixed(2)}`,20,25);ctx.fillText(eq>1?'OUTSIDE → PLASTIC':'INSIDE → ELASTIC',20,h-20);ctx.fillStyle=orange;ctx.fillText(criterion==='tresca'?'Tresca hexagon':criterion==='hill'?"Hill '48 anisotropic locus":'von Mises circle',cx-r,cy-r-14);$('#equivReadout').innerHTML=`σ̄ / σ<sub>y</sub> = ${eq.toFixed(2)}`;$('#yieldStatus').textContent=eq>1?'outside the surface → plastic loading':'inside the surface → elastic state';$('#yieldFormula').textContent=criterion==='tresca'?'σ̄ = max(|σ₁−σ₂|, |σ₂−σ₃|, |σ₃−σ₁|)':'σ̄ = √[σ₁² − σ₁σ₂ + σ₂²] (σ₃ = 0)'}
function drawHardening(){const c=$('#hardeningCanvas'),{ctx,w,h}=resizeCanvas(c),p=chartFrame(ctx,w,h,'plastic strain εᵖ','true stress σ (MPa)'),X=x=>p.l+x*(w-p.l-p.r),Y=y=>h-p.b-(y/1100)*(h-p.t-p.b),K=+$('#kHardening').value,n=+$('#nHardening').value,Q=+$('#qHardening').value;const curves=[['Hollomon',cyan,e=>K*Math.pow(e+.002,n)],['Swift',orange,e=>K*Math.pow(e+.04,n)],['Voce',lime,e=>920-Q*Math.exp(-7*e)],['Ludwik',pink,e=>250+K*Math.pow(e+.002,n)]];curves.forEach(([name,col,fn],index)=>{ctx.strokeStyle=col;ctx.lineWidth=4;ctx.beginPath();for(let i=0;i<=100;i++){const e=i/100,y=fn(e);i?ctx.lineTo(X(e),Y(y)):ctx.moveTo(X(e),Y(y))}ctx.stroke();const lx=.68+index*.07,ly=fn(lx);ctx.fillStyle=col;ctx.font='600 11px DM Mono';ctx.fillText(name,X(lx)+6,Y(ly)+index%2*13-5)});ctx.fillStyle=paper;ctx.font='600 11px DM Mono';ctx.fillText(`K=${K} MPa · n=${n.toFixed(2)} · Q=${Q} MPa`,p.l+12,p.t+18)}
function drawReverse(){const c=$('#reverseCanvas'),{ctx,w,h}=resizeCanvas(c),p=chartFrame(ctx,w,h,'total strain ε  (compression ← | → tension)','stress σ (MPa)'),X=x=>p.l+(x+.35)/1.35*(w-p.l-p.r),Y=y=>h-p.b-(y+700)/1400*(h-p.t-p.b),reversed=$('#reverseButton').dataset.reversed;ctx.strokeStyle=cyan;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(X(-.05),Y(0));ctx.bezierCurveTo(X(.12),Y(240),X(.28),Y(450),X(.42),Y(590));ctx.stroke();ctx.fillStyle=cyan;ctx.beginPath();ctx.arc(X(.42),Y(590),7,0,Math.PI*2);ctx.fill();ctx.strokeStyle=reversed?lime:orange;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(X(.42),Y(590));ctx.bezierCurveTo(X(.25),Y(330),X(reversed?.05:.1),Y(reversed?80:-30),X(reversed?-.08:-.18),Y(reversed?-150:-330));ctx.stroke();if(reversed){ctx.strokeStyle='#e78aa988';ctx.setLineDash([7,5]);ctx.beginPath();ctx.moveTo(X(-.08),Y(-150));ctx.bezierCurveTo(X(.04),Y(-40),X(.22),Y(160),X(.3),Y(350));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=lime;ctx.beginPath();ctx.arc(X(-.08),Y(-150),7,0,Math.PI*2);ctx.fill()}ctx.fillStyle=cyan;ctx.font='600 11px DM Mono';ctx.fillText('1 · forward yield / hardening',X(.12),Y(390));ctx.fillStyle=reversed?lime:orange;ctx.fillText(reversed?'2 · reverse yield reduced by backstress':'2 · click to apply compression reversal',X(-.18),Y(-270));if(reversed){ctx.fillStyle='#e78aa9';ctx.fillText('3 · reloading toward stabilized response',X(.04),Y(210))}ctx.fillStyle=paper;ctx.fillText(reversed?'Bauschinger effect: reverse yield is reached earlier':'forward-only path: no reverse memory',p.l+12,p.t+18)}
function setupCanvasInteractions(){const flc=$('#flcCanvas'),yieldCanvas=$('#yieldCanvas');let draggingYield=false,draggingFLC=false;const updateFLC=event=>{const rect=flc.getBoundingClientRect(),x=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height)),beta=-.5+x*1.5,n=.08+(1-y)*.32;$('#minorRatio').value=beta.toFixed(2);$('#nExponent').value=n.toFixed(2);$('#minorRatioValue').textContent=beta.toFixed(2);$('#nValue').textContent=n.toFixed(2);drawFLCCorrect()};flc.addEventListener('pointerdown',event=>{draggingFLC=true;flc.setPointerCapture(event.pointerId);updateFLC(event)});flc.addEventListener('pointermove',event=>{if(draggingFLC)updateFLC(event)});flc.addEventListener('pointerup',()=>{draggingFLC=false});const updateYield=event=>{const rect=yieldCanvas.getBoundingClientRect(),x=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height)),s1=-1.5+x*3.3,s2=1.8-y*3.3;$('#sigma1').value=s1.toFixed(2);$('#sigma2').value=s2.toFixed(2);$('#sigma1Value').textContent=s1.toFixed(2);$('#sigma2Value').textContent=s2.toFixed(2);drawYieldCorrect()};yieldCanvas.addEventListener('pointerdown',event=>{draggingYield=true;yieldCanvas.setPointerCapture(event.pointerId);updateYield(event)});yieldCanvas.addEventListener('pointermove',event=>{if(draggingYield)updateYield(event)});yieldCanvas.addEventListener('pointerup',()=>{draggingYield=false})}
const steps=[['01','measure','true stress + plastic strain, directional yield, r-values, FLC points'],['02','choose surface','von Mises for isotropic; Hill / Barlat when texture makes direction matter'],['03','choose memory','isotropic for monotonic; combined / Yoshida–Uemori for reversals'],['04','validate','coupon → forming test → component; compare force, thickness, strains, failure']];function renderWorkflow(){$('#workflow').innerHTML=steps.map(s=>`<div class="workflow-step"><span>${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p><em>${s[0]==='01'?'inputs':s[0]==='04'?'acceptance gate':'model decision'}</em></div>`).join('')}
function render(){repairExternalRoutes();renderEvidence();slides.forEach((s,i)=>s.classList.toggle('active',i===current));chapters.forEach((c,i)=>c.classList.toggle('active',i===current));$('#progressLabel').textContent=`${String(current+1).padStart(2,'0')} / 09`;$('#chapterTitle').textContent=chapters[current].querySelector('b').textContent;window.scrollTo({top:0,behavior:'smooth'});if(current===0)drawHero();if(current===1)renderVariable();if(current===2)renderTest();if(current===3){drawFLCCorrect();renderTopicResearch('flcResearchFeed')}if(current===4){drawYieldCorrect();renderTopicResearch('yieldResearchFeed')}if(current===5){drawHardening();renderTopicResearch('hardeningResearchFeed')}if(current===6){drawReverse();renderTopicResearch('reverseResearchFeed')}if(current===7){renderWorkflow();renderEvidence();renderTopicResearch('simulationResearchFeed')}}
chapters.forEach(c=>c.onclick=()=>{current=+c.dataset.slide;render()});$('#prevButton').onclick=()=>{current=(current+8)%9;render()};$('#nextButton').onclick=()=>{current=(current+1)%9;render()};document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();current=(current+1)%9;render()}if(e.key==='ArrowLeft'){current=(current+8)%9;render()}});$('#fullscreenButton').onclick=()=>document.documentElement.requestFullscreen?.();['minorRatio','thickness','nExponent'].forEach(id=>$('#'+id).oninput=()=>{if(id==='minorRatio')$('#minorRatioValue').textContent=(+$('#'+id).value).toFixed(2);if(id==='thickness')$('#thicknessValue').textContent=(+$('#'+id).value).toFixed(2)+' mm';if(id==='nExponent')$('#nValue').textContent=(+$('#'+id).value).toFixed(2);drawFLCCorrect()});['sigma1','sigma2'].forEach(id=>$('#'+id).oninput=()=>{$('#'+id+'Value').textContent=(+$('#'+id).value).toFixed(2);drawYieldCorrect()});$('#yieldCriterion').onchange=drawYieldCorrect;['kHardening','nHardening','qHardening'].forEach(id=>$('#'+id).oninput=()=>{const map={kHardening:['kValue',v=>v+' MPa'],nHardening:['nHardValue',v=>(+v).toFixed(2)],qHardening:['qValue',v=>v+' MPa']};const [out,fmt]=map[id];$('#'+out).textContent=fmt($('#'+id).value);drawHardening()});$('#reverseButton').onclick=()=>{$('#reverseButton').dataset.reversed=$('#reverseButton').dataset.reversed?'':'1';$('#reverseReadout').textContent=$('#reverseButton').dataset.reversed?'Yoshida–Uemori captures the transient reverse response':'forward-only model overpredicts reverse strength';$('#reverseButton').textContent=$('#reverseButton').dataset.reversed?'↺ reset to forward-only':'↻ apply compression reversal';drawReverse()};setupCanvasInteractions();window.onresize=()=>render();render();